			return
		}
		mu.Lock()
		defer mu.Unlock()
		fmt.Fprintf(deps.stderr, "[runtime] %-18s", progress.Stage)
		if progress.Task != "" {
			fmt.Fprintf(deps.stderr, " task=%s", progress.Task)
		}
		if progress.CoverageID != "" {
			fmt.Fprintf(deps.stderr, " coverage=%s", progress.CoverageID)
		}
