// Verify is the sole review-to-smoke transition. It requires complete execute
// evidence, reuses current canonical review evidence, and applies the smoke gate.
func (s Service) Verify(ctx context.Context, projectRef, sprintRef string, req VerifyRequest) (VerifyResult, error) {
	if !req.DryRun {
		lockedCtx, release, lockErr := s.acquireMutationContext(ctx, projectRef, sprintRef)
		if lockErr != nil {
			return VerifyResult{}, lockErr
		}
		defer release()
		ctx = lockedCtx
	}
	if req.To == "" {
		req.To = StageSmoke
	}
	if req.To != StageReview && req.To != StageSmoke {
		return VerifyResult{}, fmt.Errorf("verify target must be review or smoke")
	}
	result := VerifyResult{Project: projectRef, Sprint: sprintRef, To: req.To, DryRun: req.DryRun}
	if err := s.requireCompleteExecute(projectRef, sprintRef); err != nil {
		return result, err
	}
	status, statusErr := s.VerificationStatus(projectRef, sprintRef)
	if statusErr != nil && !errors.Is(statusErr, ErrFlowStateMissing) {
		return result, statusErr
	}
	if statusErr == nil {
		result.Verification = status
	}
	currentReview := statusErr == nil && status.Review.Fresh && status.Review.ExecutionStatus == string(ReviewCompleted) && !req.Review.Restart
	if !currentReview {
		if req.Progress != nil {
			req.Progress(FlowProgress{Stage: StageReview, State: "running", Message: "obtaining current review evidence"})
		}
		reviewReq := req.Review
		reviewReq.DryRun = req.DryRun
		review, err := s.Review(ctx, projectRef, sprintRef, reviewReq)
		result.ReviewResult = &review
		allowDiagnosticContinuation := req.To == StageSmoke && review.Status == ReviewCompleted && review.Verdict == ReviewFail && req.Smoke.ForceReview && req.Smoke.OverrideConfirmed && strings.TrimSpace(req.Smoke.OverrideRationale) != ""
		if err != nil && !allowDiagnosticContinuation {
			return result, err
		}
	} else if req.Progress != nil {
		req.Progress(FlowProgress{Stage: StageReview, State: "skipped", Message: "current review evidence is acceptable"})
	}
	if req.To == StageReview || req.DryRun {
		if !req.DryRun {
			result.Verification, _ = s.VerificationStatus(projectRef, sprintRef)
		}
		return result, nil
	}
	if req.Progress != nil {
		req.Progress(FlowProgress{Stage: StageSmoke, State: "running", Message: "evaluating review gate and running smoke"})
	}
	smokeReq := req.Smoke
	smoke, err := s.RunSmoke(ctx, projectRef, sprintRef, smokeReq)
	result.SmokeResult = &smoke
	result.Verification, _ = s.VerificationStatus(projectRef, sprintRef)
	return result, err
}

func (s Service) requireCompleteExecute(projectRef, sprintRef string) error {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return err
	}
	state, err := LoadExecuteRunState(s.root, sp)
	if err != nil {
		path, pathErr := ExecuteRunStatePath(s.root, sp)
		if pathErr == nil {
			var summary struct {
				Status string   `json:"status"`
				Files  []string `json:"files"`
			}
			if data, readErr := os.ReadFile(path); readErr == nil && json.Unmarshal(data, &summary) == nil && (summary.Status == "complete" || summary.Status == "completed") && len(summary.Files) > 0 {
				content, artifactErr := s.store.ReadArtifact(sp, StageExecute)
				if artifactErr == nil && strings.TrimSpace(content) != "" {
					return nil
				}
			}
		}
		return fmt.Errorf("execute evidence is incomplete: %w", err)
	}
	if len(state.Tasks) == 0 {
		return fmt.Errorf("execute evidence is incomplete: no planned tasks")
	}
	for _, task := range state.Tasks {
		if task.Status != ExecuteTaskComplete && task.Status != ExecuteTaskDeferred {
			return fmt.Errorf("execute evidence is incomplete: task %q is %s", task.Identity.Name, task.Status)
		}
	}
	data, err := s.store.ReadArtifact(sp, StageExecute)
	if err != nil || strings.TrimSpace(data) == "" {
		return fmt.Errorf("execute evidence is incomplete: execute.md is missing")
	}
	return nil
}

func (s Service) ExecuteComplete(projectRef, sprintRef string) (bool, error) {
	err := s.requireCompleteExecute(projectRef, sprintRef)
	if err != nil {
		return false, nil
	}
	return true, nil
}

func (s Service) VerificationStatus(projectRef, sprintRef string) (VerificationStatus, error) {
	sp, _, _, err := s.resolveSprintInputs(projectRef, sprintRef)
	if err != nil {
		return VerificationStatus{}, err
	}
	out := VerificationStatus{Project: sp.Project, Sprint: sp.Slug}
	out.Review = VerificationStage{Stage: StageReview, ExecutionStatus: "missing", Artifact: ArtifactRelPath(sp, StageReview), NextAction: "Run review."}
	out.Smoke = VerificationStage{Stage: StageSmoke, ExecutionStatus: "missing", Artifact: ArtifactRelPath(sp, StageSmoke), NextAction: "Run smoke after a current acceptable review."}
	state, err := LoadFlowState(s.root, sp)
	if err != nil {
		return out, err
	}
	// Status derives expired-attempt truth without mutating durable state.
	// The next explicit review/smoke operation owns any persisted transition.
	reconcileExpiredAttempts(&state, s.now().UTC())
	malformed := false
	if state.Review != nil {
		r := state.Review
		out.Review.ExecutionStatus, out.Review.Verdict = string(r.Status), string(r.Verdict)
		out.Review.InputFingerprint, out.Review.ArtifactDigest = r.Fingerprint, r.ArtifactDigest
		out.Review.ActiveAttempt, out.Review.LastAttempt = r.ActiveAttempt, r.LastAttempt
		if r.Resume != nil {
			out.Review.Total = len(r.Resume.Coverage)
			for _, checkpoint := range r.Resume.Coverage {
				if checkpoint.Status == AttemptCompleted {
					out.Review.Completed++
				}
				if checkpoint.SessionID != "" && checkpoint.Status != AttemptCompleted {
					out.Review.RetainedSessions++
				}
			}
			out.Review.Resumable = out.Review.Completed > 0
		}
		manifest, findings, prepareErr := s.PrepareReview(projectRef, sprintRef, ReviewRequest{})
		if prepareErr != nil || len(findings) > 0 {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "governed review inputs are unavailable or invalid")
		} else if strictCompletedReviewSnapshotFreshness && manifest.Fingerprint != r.Fingerprint {
			out.Review.FreshnessReasons = append(out.Review.FreshnessReasons, "review input fingerprint changed")
		}

package sprint

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

const stageSessionSchemaVersion = 1

type stageSessionRecord struct {
	SessionID      string    `json:"sessionId"`
	Provider       string    `json:"provider,omitempty"`
	Model          string    `json:"model,omitempty"`
	WorkDir        string    `json:"workDir"`
	PromptChecksum string    `json:"promptChecksum,omitempty"`
	UpdatedAt      time.Time `json:"updatedAt"`
}

type stageSessionState struct {
	SchemaVersion int                           `json:"schemaVersion"`
	Sessions      map[string]stageSessionRecord `json:"sessions"`
}

func stageSessionPath(sp Sprint) string { return filepath.Join(sp.Path, ".stage-sessions.json") }

func loadStageSessions(sp Sprint) (stageSessionState, error) {
	path := stageSessionPath(sp)
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return stageSessionState{SchemaVersion: stageSessionSchemaVersion, Sessions: map[string]stageSessionRecord{}}, nil
	}
	if err != nil {
		return stageSessionState{}, err
	}
	var state stageSessionState
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&state); err != nil {
		return stageSessionState{}, fmt.Errorf("decode stage sessions: %w", err)
	}
	var trailing any
	if err := dec.Decode(&trailing); !errors.Is(err, io.EOF) {
		return stageSessionState{}, fmt.Errorf("decode stage sessions: trailing JSON")
	}
	if state.SchemaVersion != stageSessionSchemaVersion || state.Sessions == nil {
		return stageSessionState{}, fmt.Errorf("unsupported stage session state")
	}
	return state, nil
}

func saveStageSessions(sp Sprint, state stageSessionState) error {
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path := stageSessionPath(sp)
	tmp, err := os.CreateTemp(sp.Path, ".stage-sessions.*.tmp")
	if err != nil {
		return err
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Chmod(0o600)
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

func stageSessionCompatible(record stageSessionRecord, req pruntime.Request) bool {
	// Prompt checksums are retained for diagnostics only. Exact prompt matching
	// would make interrupted-session recovery brittle after harmless artifact
	// edits; the continuation explicitly tells the agent to reread current state.
	return record.SessionID != "" && record.Provider == req.Provider && record.Model == req.Model && record.WorkDir == req.WorkDir
}

func stageSessionKey(stage PlanningStage, req pruntime.Request) string {
	parts := []string{string(stage)}
	for _, dimension := range []string{"task", "coverage", "area"} {
		parts = append(parts, strings.TrimSpace(req.Metadata[dimension]))
	}
	if parts[1] == "" && parts[2] == "" && parts[3] == "" {
		return parts[0]
	}
	return strings.Join(parts, ":")
}

func (s Service) startPlanningStageRun(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	key := stageSessionKey(stage, req)
	originalPrompt := req.Prompt
	continuing := false
	state, loadErr := loadStageSessions(sp)
	if loadErr == nil {
		if record, ok := state.Sessions[key]; ok && stageSessionCompatible(record, req) {
			req.SessionID = record.SessionID
			req.SessionAction = "continue"
			req.Prompt = insertStageContinuation(req.Prompt, "Continue the interrupted UltraPlan stage from the existing session. Re-read the current stage prompt and filesystem state, then finish only the requested stage.")
			continuing = true
		}
	}
	previousOnEvent := req.OnEvent
	var mu sync.Mutex
	lastSession := req.SessionID
	persist := func(sessionID string) {
		if strings.TrimSpace(sessionID) == "" {
			return
		}
		mu.Lock()
		defer mu.Unlock()
		if sessionID == lastSession {
			return
		}
		lastSession = sessionID
		current, err := loadStageSessions(sp)
		if err != nil {
			return
		}
		current.Sessions[key] = stageSessionRecord{SessionID: sessionID, Provider: req.Provider, Model: req.Model, WorkDir: req.WorkDir, PromptChecksum: req.PromptRef.Checksum, UpdatedAt: s.now().UTC()}
		_ = saveStageSessions(sp, current)
	}
	req.OnEvent = func(event pruntime.Event) {
		if previousOnEvent != nil {
			previousOnEvent(event)
		}
		persist(event.SessionID)
	}
	result, err := s.startSprintRuntime(ctx, sp, stage, req)
	persist(result.SessionID)
	if continuing && planningSessionNotFound(result, err) && ctx.Err() == nil {
		_ = clearPlanningStageSessionKey(sp, key)
		lastSession = ""
		req.SessionID = ""
		req.SessionAction = "fresh"
		req.Prompt = originalPrompt
		result, err = s.startSprintRuntime(ctx, sp, stage, req)
		persist(result.SessionID)
	}
	return result, err
}

func planningSessionNotFound(result pruntime.Result, err error) bool {
	var details []string
	if err != nil {
		details = append(details, err.Error())
	}
	details = append(details, result.TerminalOutput)
	if result.Error != nil {
		details = append(details, result.Error.UserDetail, result.Error.DebugDetail)
	}
	for _, attempt := range result.Attempts {
		details = append(details, attempt.ErrorDetail)
	}
	return strings.Contains(strings.ToLower(strings.Join(details, "\n")), "session not found")
}

func insertStageContinuation(prompt, instruction string) string {
	boundary := strings.Index(prompt, sharedPromptStageBoundary)
	if boundary < 0 {
		return instruction + "\n\n" + prompt
	}
	boundary += len(sharedPromptStageBoundary)
	return prompt[:boundary] + instruction + "\n\n" + prompt[boundary:]
}

func clearPlanningStageSession(sp Sprint, stage PlanningStage) error {
	state, err := loadStageSessions(sp)
	if err != nil {
		return err
	}
	found := false
	for key := range state.Sessions {
		if key == string(stage) || strings.HasPrefix(key, string(stage)+":") {
			delete(state.Sessions, key)
			found = true
		}
	}
	if !found {
		return nil
	}
	return saveOrRemoveStageSessions(sp, state)
}

func clearPlanningStageSessionKey(sp Sprint, key string) error {
	state, err := loadStageSessions(sp)
	if err != nil {
		return err
	}
	if _, ok := state.Sessions[key]; !ok {
		return nil
	}
	delete(state.Sessions, key)
	return saveOrRemoveStageSessions(sp, state)
}

func saveOrRemoveStageSessions(sp Sprint, state stageSessionState) error {
	if len(state.Sessions) == 0 {
		if err := os.Remove(stageSessionPath(sp)); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
		return nil
	}
	return saveStageSessions(sp, state)
}

func (s Service) cleanupPlanningStageSession(ctx context.Context, sp Sprint, stage PlanningStage, sessionID string) error {
	if err := s.deleteCompletedSession(ctx, sessionID); err != nil {
		return err
	}
	return clearPlanningStageSession(sp, stage)
}

func (s Service) cleanupPlanningStageSessions(ctx context.Context, sp Sprint, stage PlanningStage, result pruntime.Result) error {
	if err := s.deleteCompletedSessions(ctx, result); err != nil {
		return err
	}
	return clearPlanningStageSession(sp, stage)
}

