package sprint

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func probeHarness(t *testing.T) (string, Sprint, string, *smokeRecordingRunner, *smokeAuthorRuntime) {
	t.Helper()
	root, sp := reviewFixture(t)
	writeFileContent(t, filepath.Join(root, "projects", "proj"), `# Roadmap

## Phase 1: Delivery

### Sprint 1: Alpha

> Slug: 01-alpha
> Status: active

#### Goal

Complete alpha.

#### Build

- implementation

#### Acceptance

- [ ] smoke passes
`, "roadmap.md")
	harness := t.TempDir()
	writeFileContent(t, harness, "#!/bin/sh\n", "runner")
	if err := os.Chmod(filepath.Join(harness, "runner"), 0o755); err != nil {
		t.Fatal(err)
	}
	for _, dir := range []string{"runs", "issues", "suite"} {
		if err := os.MkdirAll(filepath.Join(harness, dir), 0o755); err != nil {
			t.Fatal(err)
		}
	}
	manifest := `{"schemaVersion":1,"protocolVersion":"1.0","harness":{"id":"fake","version":"1"},"executable":"runner","cwd":".","commands":{"discover":["discover"],"run":["run"]},"evidence":{"runs":"runs","issues":"issues"},"authoring":{"paths":["suite"]},"capabilities":["discovery","run","evidence-v1","scope-mapping","authoring-v1"],"environment":[]}`
	writeFileContent(t, harness, manifest, "manifest.json")
	projectIndexPath := filepath.Join(root, "projects", "proj", "project-index.md")
	data, _ := os.ReadFile(projectIndexPath)
	data = append(data, []byte("\n## Smoke Harnesses\n\n| Harness | Path | Manifest | Evidence | Useful For | Status |\n|---|---|---|---|---|---|\n| fake | "+harness+" | "+filepath.Join(harness, "manifest.json")+" | runs/ and issues/ | tests | current |\n")...)
	if err := os.WriteFile(projectIndexPath, data, 0o644); err != nil {
		t.Fatal(err)
	}
	return root, sp, harness, &smokeRecordingRunner{}, &smokeAuthorRuntime{}
}

func probePassResponse(runID string) smokeRunResponse {
	return smokeRunResponse{SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", RunID: runID, ScopeKind: "suite", Scope: []string{"sprint"}, Counts: SmokeCountsWire{Total: 1, Passed: 1}, Tests: []SmokeTestResult{{ID: "live", Status: "passed"}}, DurationMs: 10, Evidence: []smokeEvidenceWire{{Kind: "run", Path: "runs/" + runID + ".json"}}}
}

func TestProbeDiagnosticFailureLeavesStalePassState(t *testing.T) {
	root, sp, harness, runner, author := probeHarness(t)
	runID := "run-1"
	if err := os.WriteFile(filepath.Join(harness, "runs", runID+".json"), []byte("{}\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runner.discovery = smokeDiscovery{SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", EvidenceSchema: 1, Suites: []smokeSuite{{ID: "sprint", Tests: []string{"live"}}}, Tests: []smokeTest{{ID: "live", Suite: "sprint", Coverage: []string{"real-boundary"}}}, SprintMappings: []smokeSprintMapping{{Sprint: sp.Slug, Suites: []string{"sprint"}, Complete: true, RequiredCoverage: []string{"real-boundary"}, Rationale: "dedicated"}}}
	runner.run = probePassResponse(runID)
	service := NewService(root).WithRuntime(author).WithProcessRunner(runner).WithSmokeSettings(DefaultSmokeSettings()).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "test/model"}, StageSmoke: {Model: "test/author"}})
	base, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{})
	if err != nil || base.Verdict != SmokePass {
		t.Fatalf("baseline run: verdict=%s err=%v", base.Verdict, err)
	}

	diagID := "run-2"
	if err := os.WriteFile(filepath.Join(harness, "runs", diagID+".json"), []byte("{}\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(harness, "issues", "ISS-1.md"), []byte("# issue\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	runner.run = smokeRunResponse{
		SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", RunID: diagID,
		ScopeKind: "test", Scope: []string{"live"},
		Counts:    SmokeCountsWire{Total: 1, Failed: 1},
		Tests:     []SmokeTestResult{{ID: "live", Status: "failed"}},
		DurationMs: 5,
		Evidence:  []smokeEvidenceWire{{Kind: "run", Path: "runs/" + diagID + ".json"}},
		Issues: []SmokeIssue{{ID: "ISS-1", Status: "open", Path: "issues/ISS-1.md", TestID: "live", Severity: "high", Title: "t", Summary: "s", Theory: "th", Evidence: "e", Action: "a"}},
	}
	result, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{Test: "live"})
	if err != nil || !result.DiagnosticOnly || result.Verdict != SmokeFailVerdict {
		t.Fatalf("diagnostic run: verdict=%s diagnostic=%t err=%v", result.Verdict, result.DiagnosticOnly, err)
	}

	state, stateErr := LoadFlowState(root, sp)
	if stateErr != nil || state.Smoke == nil {
		t.Fatalf("flow state: %v", stateErr)
	}
	t.Logf("AFTER DIAGNOSTIC FAIL: status=%q verdict=%q runID=%q lastAttempt=%+v", state.Smoke.Status, state.Smoke.Verdict, state.Smoke.RunID, state.Smoke.LastAttempt)
	if state.Smoke.Status != SmokeCompleted || state.Smoke.Verdict != SmokePass || state.Smoke.RunID != runID {
		t.Fatalf("PREDICTION WRONG: status=%q verdict=%q runID=%q", state.Smoke.Status, state.Smoke.Verdict, state.Smoke.RunID)
	}
	if state.Smoke.LastAttempt == nil || state.Smoke.LastAttempt.Status != AttemptCompleted || len(state.Smoke.LastAttempt.Diagnostics) != 0 {
		t.Fatalf("last attempt does not record the failure: %+v", state.Smoke.LastAttempt)
	}
	validation, _ := service.ValidateSmoke("proj", "01")
	if len(validation.Findings) != 0 {
		t.Fatalf("validate reports findings: %+v", validation.Findings)
	}
	status, statusErr := service.VerificationStatus("proj", "01")
	if statusErr != nil {
		t.Fatal(statusErr)
	}
	t.Logf("VERIFICATION AFTER DIAGNOSTIC FAIL: assessment=%s smokeFresh=%t smokeVerdict=%s", status.Assessment, status.Smoke.Fresh, status.Smoke.Verdict)
	if status.Assessment != AssessmentPass || !status.Smoke.Fresh || status.Smoke.Verdict != string(SmokePass) {
		t.Fatalf("PREDICTION WRONG: assessment=%s fresh=%t verdict=%s", status.Assessment, status.Smoke.Fresh, status.Smoke.Verdict)
	}
	prior, _ := os.ReadFile(filepath.Join(sp.Path, "smoke.md"))
	if !strings.Contains(string(prior), "Verdict: `pass`") {
		t.Fatal("smoke.md no longer shows the pass verdict")
	}
	t.Log("CONFIRMED: failing diagnostic probe leaves completed/pass flow state, clean validation, pass assessment")
}

func TestProbeManifestEnvironmentIsInert(t *testing.T) {
	settings := DefaultSmokeSettings()
	values := map[string]string{"PATH": "/usr/bin", "HOME": "/home/x", "EXTRA_OK": "granted-by-manifest", "OPERATOR_SECRET": "forwarded-without-manifest"}
	getenv := func(name string) string { return values[name] }

	env := smokeEnvironment(settings, smokeManifest{Environment: []string{"EXTRA_OK"}}, getenv)
	joined := strings.Join(env, ";")
	if strings.Contains(joined, "EXTRA_OK=") {
		t.Fatalf("manifest declaration granted a name outside the operator allowlist: %v", env)
	}
	if !strings.Contains(joined, "OPERATOR_SECRET=") {
		t.Fatalf("allowlist name not declared by any manifest was withheld: %v", env)
	}
	restricted := SmokeSettings{DiscoveryTimeout: settings.DiscoveryTimeout, RunTimeout: settings.RunTimeout, CleanupGrace: settings.CleanupGrace, StdoutLimit: settings.StdoutLimit, StderrLimit: settings.StderrLimit, Environment: []string{"OPERATOR_SECRET"}, Getenv: getenv}
	env = smokeEnvironment(restricted, smokeManifest{}, getenv)
	if len(env) != 1 || !strings.HasPrefix(env[0], "OPERATOR_SECRET=") {
		t.Fatalf("operator allowlist forwarding diverged: %v", env)
	}
	t.Logf("CONFIRMED inert manifest env: declared-but-unallowed EXTRA_OK dropped; allowed-but-undeclared OPERATOR_SECRET forwarded: %v", env)
}
EOF
